package vn.iotstar.security; import lombok.RequiredArgsConstructor; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service; import vn.iotstar.entity.User; import vn.iotstar.repository.UserRepository;
@Service @RequiredArgsConstructor public class CustomUserDetailsService implements UserDetailsService { private final UserRepository users; public UserDetails loadUserByUsername(String login)throws UsernameNotFoundException{User u=users.findByUsernameOrEmail(login,login).orElseThrow(()->new UsernameNotFoundException("Không tìm thấy username/email: "+login)); return new CustomUserDetails(u.getId(),u.getUsername(),u.getEmail(),u.getPassword(),u.getFullName(),u.getImages(),u.getRole().getName(),u.isEnabled());} }
